// Get raw extracted text
let rawText = items[0].json.text;

// 1. Remove headers, footers, and metadata
rawText = rawText.replace(/Title:.*?\n/gi, '');
rawText = rawText.replace(/Duration:.*?\n/gi, '');
rawText = rawText.replace(/Participants:[\s\S]*?---\n/gi, '');
rawText = rawText.replace(/---\nEnd of Transcript/gi, '');
rawText = rawText.replace(/---/g, '');

// 2. Fix PDF line breaks (join broken sentences)
rawText = rawText.replace(/(\w)\n(\w)/g, '$1 $2');

// 3. Normalize speaker labels (ensure "Speaker: sentence")
rawText = rawText.replace(/\n?(Pranadir|Alex):\s*/g, '\n$1: ');

// 4. Remove excessive newlines and spaces
rawText = rawText.replace(/\n{2,}/g, '\n');
rawText = rawText.trim();

// 5. Optional: final formatting for AI
const normalizedTranscript = rawText;

return [
  {
    json: {
      normalizedTranscript
    }
  }
];

