// Get raw JSON string from AI Agent
const raw = items[0].json.output;

// Parse JSON string safely
const parsed = JSON.parse(raw);

// HARD NORMALIZATION (remove reasoning drift)
parsed.decision_signals.urgency_level =
  parsed.decision_signals.urgency_level?.split(';')[0] || null;

parsed.decision_signals.buying_intent_signal =
  parsed.decision_signals.buying_intent_signal?.split(';')[0] || null;

parsed.constraints_and_preferences.complexity_tolerance =
  parsed.constraints_and_preferences.complexity_tolerance?.split(';')[0] || null;

parsed.constraints_and_preferences.tools_resistance =
  parsed.constraints_and_preferences.tools_resistance?.split(';')[0] || null;

// Optional: enforce nulls if inferred
if (parsed.client_profile.company_size_signal === "Growing quickly") {
  parsed.client_profile.company_size_signal = null;
}

return [{ json: parsed }];
